import React, { forwardRef, useImperativeHandle, useLayoutEffect, useEffect, useMemo, useRef, useState } from 'react';
import { AccessibilityInfo, PanResponder, StyleSheet, View, type ViewStyle } from 'react-native';
import { Canvas, Fill, ImageShader, Shader, Skia, makeImageFromView, type SkImage } from '@shopify/react-native-skia';
import { cancelAnimation, Easing, runOnJS, useDerivedValue, useSharedValue, withTiming } from 'react-native-reanimated';
import { curlGeometry, dragProgress, shouldTurn, targetPage, SKSL } from './curlMath';

export type CurlPage = { image: SkImage; backImage?: SkImage; label?: string };
export type PageCurlProps = {
  pages: readonly CurlPage[]; width: number; height: number; initialPage?: number;
  reducedMotion?: boolean; onPageChange?: (index: number) => void;
  style?: ViewStyle; label?: string;
};
// Capture deliberately, after layout/fonts/images are ready, not during a gesture.
// The caller owns returned images and must dispose them after the pager unmounts.
export async function snapshotPage(ref: React.RefObject<View | null>): Promise<SkImage> {
  if (!ref.current) throw new Error('Page view is not mounted');
  const image = await makeImageFromView(ref);
  if (!image) throw new Error('Page snapshot failed');
  return image;
}
const effect = (() => { const e = Skia.RuntimeEffect.Make(SKSL); if (!e) throw new Error('Page Curl shader failed to compile'); return e; })();
export type PageCurlHandle = { next: () => void; previous: () => void };
export const PageCurl = forwardRef<PageCurlHandle, PageCurlProps>(function PageCurl({ pages, width, height, initialPage = 0, reducedMotion, onPageChange, style, label = 'Page reader' }, ref) {
  const [index, setIndex] = useState(() => targetPage(initialPage, 0, pages.length));
  const [direction, setDirection] = useState(1), [systemReduce, setSystemReduce] = useState(false);
  const progress = useSharedValue(0), tilt = useSharedValue(0), originY = useSharedValue(height);
  const busy = useRef(false), dragDir = useRef(1), mounted = useRef(true);
  const latest = useRef({ index, pages, width, height, reducedMotion, systemReduce, onPageChange });
  latest.current = { index, pages, width, height, reducedMotion, systemReduce, onPageChange };
  useEffect(() => {
    mounted.current = true;
    AccessibilityInfo.isReduceMotionEnabled().then(v => { if (mounted.current) setSystemReduce(v); }).catch(() => {});
    const sub = AccessibilityInfo.addEventListener('reduceMotionChanged', setSystemReduce);
    return () => { mounted.current = false; sub.remove(); cancelAnimation(progress); };
  }, [progress]);
  // A page collection or size change cancels an in-flight turn rather than committing stale content.
  useEffect(() => { cancelAnimation(progress); progress.value = 0; busy.current = false; setIndex(i => targetPage(i, 0, pages.length)); }, [pages, width, height, progress]);
  const complete = (commit: boolean, dir: number) => {
    if (!mounted.current) return;
    const l = latest.current;
    if (commit) { const next = targetPage(l.index, dir, l.pages.length); setIndex(next); l.onPageChange?.(next); AccessibilityInfo.announceForAccessibility?.(`Page ${next + 1} of ${l.pages.length}`); }
    if (!commit) { progress.value = 0; busy.current = false; }
  };
  useLayoutEffect(() => { progress.value = 0; busy.current = false; }, [index, progress]);
  const settle = (commit: boolean) => {
    busy.current = true;
    const dir = dragDir.current, l = latest.current;
    if (l.reducedMotion ?? l.systemReduce) { complete(commit, dir); return; }
    progress.value = withTiming(commit ? 1 : 0, { duration: 420, easing: Easing.out(Easing.cubic) }, done => { if (done) runOnJS(complete)(commit, dir); });
  };
  const turn = (dir: number) => {
    const l = latest.current;
    if (busy.current || targetPage(l.index, dir, l.pages.length) === l.index) return;
    dragDir.current = dir; setDirection(dir); tilt.value = 0; originY.value = l.height; settle(true);
  };
  useImperativeHandle(ref, () => ({ next: () => turn(1), previous: () => turn(-1) }));
  const responder = useMemo(() => PanResponder.create({
    onStartShouldSetPanResponder: e => {
      const l = latest.current, x = e.nativeEvent.locationX;
      return !busy.current && (x < l.width * 0.25 || x > l.width * 0.75);
    },
    onPanResponderGrant: e => {
      const l = latest.current, x = e.nativeEvent.locationX;
      const dir = x > l.width / 2 ? 1 : -1;
      dragDir.current = dir; setDirection(dir); tilt.value = 0; originY.value = e.nativeEvent.locationY;
      busy.current = true;
    },
    onPanResponderMove: (_, g) => {
      const l = latest.current, dir = dragDir.current;
      if (targetPage(l.index, dir, l.pages.length) === l.index) return;
      progress.value = dragProgress(g.dx, l.width, dir);
      tilt.value = (l.reducedMotion ?? l.systemReduce) ? 0 : Math.max(-0.55, Math.min(0.55, g.dy / Math.max(40, Math.abs(g.dx)) * dir * 0.5));
    },
    onPanResponderRelease: (_, g) => {
      const l = latest.current, dir = dragDir.current;
      settle(targetPage(l.index, dir, l.pages.length) !== l.index && shouldTurn(progress.value, g.vx, dir));
    },
    onPanResponderTerminate: () => settle(false), onPanResponderTerminationRequest: () => false,
  // Handlers read latest props; shared values retain identity.
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }), [progress, tilt, originY]);
  const reduce = reducedMotion ?? systemReduce;
  const uniforms = useDerivedValue(() => ({ size: [width, height], ...curlGeometry(progress.value, tilt.value, originY.value, width), progress: reduce ? 0 : progress.value, direction }));
  if (!pages.length || width <= 0 || height <= 0) return null;
  const current = pages[index], next = pages[targetPage(index, direction, pages.length)];
  if (!current || !next) return null;
  const rect = { x: 0, y: 0, width, height };
  return <View style={[{ width, height, overflow: 'hidden', borderRadius: 4 }, style]} {...responder.panHandlers}
    accessible accessibilityRole="adjustable" accessibilityLabel={label} accessibilityValue={{ min: 1, max: pages.length, now: index + 1, text: current.label || `Page ${index + 1}` }}
    accessibilityActions={[{ name: 'increment', label: 'Next page' }, { name: 'decrement', label: 'Previous page' }]}
    onAccessibilityAction={e => turn(e.nativeEvent.actionName === 'increment' ? 1 : -1)}>
    <Canvas pointerEvents="none" style={StyleSheet.absoluteFill}>
      <Fill><Shader source={effect} uniforms={uniforms}>
        <ImageShader image={current.image} fit="fill" rect={rect} tx="clamp" ty="clamp" />
        <ImageShader image={next.image} fit="fill" rect={rect} tx="clamp" ty="clamp" />
        <ImageShader image={current.backImage ?? current.image} fit="fill" rect={rect} tx="clamp" ty="clamp" />
      </Shader></Fill>
    </Canvas>
  </View>;
});

export const clamp = (v: number, lo: number, hi: number) => {
  'worklet'; return Math.min(hi, Math.max(lo, v));
};
export function curlGeometry(progress: number, tilt: number, originY: number, width: number) {
  'worklet';
  const radius = width * 0.115;
  const t = clamp(tilt, -0.55, 0.55), k = Math.sqrt(1 + t * t);
  return { axis: [width + Math.PI * radius / 2 - clamp(progress, 0, 1) * (width + Math.PI * radius + radius), originY], normal: [1 / k, t / k], radius };
}
export function dragProgress(dx: number, width: number, direction: number) {
  'worklet'; return clamp(-dx * direction / (width * 1.15), 0, 1);
}
export function shouldTurn(progress: number, velocityX: number, direction: number) {
  'worklet'; const v = -velocityX * direction;
  return v > 0.45 || (v > -0.45 && progress > 0.38);
}
export function targetPage(index: number, direction: number, count: number) {
  'worklet'; return clamp(index + direction, 0, Math.max(0, count - 1));
}
// Original inverse projection of a sheet wrapped around a cylinder.
// Distance from the fold axis projects to r*sin(theta). Two inverse angles
// give the front and back. The returning sheet is flat after theta=pi.
// Sampling functions are supplied by SkSL (child shaders) or WebGL (textures).
export const CURL_BODY = `
vec4 shadeBack(vec2 q, float light) {
  vec4 c = sampleBack(q);
  c.rgb = mix(c.rgb, vec3(0.97, 0.95, 0.88), 0.72) * light;
  return c;
}
bool inside(vec2 q) { return q.x >= 0.0 && q.x <= size.x && q.y >= 0.0 && q.y <= size.y; }
vec4 renderCurl(vec2 p) {
  if (progress <= 0.0001) return sampleFront(p);
  if (progress >= 0.9999) return sampleUnder(p);
  float s = dot(p-axis, normal);
  vec2 along = p - normal*s;
  vec4 under = sampleUnder(p);
  // Contact shadow sits beneath the projected cylinder, follows the axis.
  float sh = exp(-abs(s-radius*0.45)/(radius*0.75)) * 0.27;
  under.rgb *= 1.0-sh;
  if (s > radius) return under;
  if (s < 0.0) {
    vec2 back = along + normal*(3.14159265*radius - s);
    if (inside(back)) return shadeBack(back, 0.94);
    return sampleFront(p);
  }
  float theta = asin(clamp(s/radius, 0.0, 1.0));
  vec2 back = along + normal*((3.14159265-theta)*radius);
  float light = 0.70 + 0.27*cos(theta);
  if (inside(back)) return shadeBack(back, light);
  vec2 front = along + normal*(theta*radius);
  if (inside(front)) {
    vec4 c = sampleFront(front);
    c.rgb *= 0.74 + 0.26*cos(theta);
    return c;
  }
  return under;
}`;
export const SKSL = `
uniform shader frontPage;
uniform shader underPage;
uniform shader backPage;
uniform float2 size;
uniform float2 axis;
uniform float2 normal;
uniform float radius;
uniform float progress;
uniform float direction;
float2 sourcePoint(float2 p) { return float2(direction < 0.0 ? size.x-p.x : p.x, p.y); }
float4 sampleFront(float2 p) { return float4(frontPage.eval(sourcePoint(p))); }
float4 sampleUnder(float2 p) { return float4(underPage.eval(sourcePoint(p))); }
float4 sampleBack(float2 p) { return float4(backPage.eval(sourcePoint(p))); }
${CURL_BODY.replace(/vec2/g, 'float2').replace(/vec3/g, 'float3').replace(/vec4/g, 'float4')}
half4 main(float2 p) { return half4(renderCurl(sourcePoint(p))); }
`;

import React, { useEffect, useMemo, useState, useRef } from 'react';
import { Pressable, Text, View } from 'react-native';
import { Skia } from '@shopify/react-native-skia';
import { PageCurl, type PageCurlHandle } from './PageCurl';
const COLORS = ['#e6edde', '#dce9eb', '#f0e2ce'];
export default function Example() {
  const [reduce, setReduce] = useState(false), [index, setIndex] = useState(0);
  const pager = useRef<PageCurlHandle>(null);
  const pages = useMemo(() => COLORS.map((color, i) => {
    const surface = Skia.Surface.MakeOffscreen(600, 800);
    if (!surface) throw new Error('Unable to prepare page');
    const c = surface.getCanvas(), paint = Skia.Paint();
    c.clear(Skia.Color(color)); paint.setColor(Skia.Color('#214b3b'));
    c.drawRect(Skia.XYWHRect(48, 48, 130, 8), paint);
    c.drawRect(Skia.XYWHRect(48, 100, 330 - i*50, 16), paint);
    paint.setColor(Skia.Color(['#86a887', '#7eacb3', '#c4a47d'][i]));
    c.drawCircle(310, 435, 185, paint); paint.setColor(Skia.Color('#214b3b'));
    for (let j = 0; j <= i; j++) c.drawCircle(54 + j*24, 750, 6, paint);
    surface.flush(); const snapshot = surface.makeImageSnapshot();
    const image = snapshot.makeNonTextureImage(); snapshot.dispose(); surface.dispose(); paint.dispose();
    if (!image) throw new Error("Unable to copy page image");
    return { image, label: `Field notes ${i + 1}` };
  }), []);
  useEffect(() => () => { pages.forEach(p => p.image.dispose()); }, [pages]);
  return <View style={{ alignItems: 'center', gap: 20 }}><PageCurl ref={pager} onPageChange={setIndex} pages={pages} width={300} height={400} reducedMotion={reduce ? true : undefined} /><View style={{ flexDirection: 'row', gap: 32, alignItems: 'center' }}><Pressable accessibilityRole="button" accessibilityLabel="Previous page" disabled={index === 0} onPress={() => pager.current?.previous()} style={{ padding: 12 }}><Text>←</Text></Pressable><Text>{index + 1} / 3</Text><Pressable accessibilityRole="button" accessibilityLabel="Next page" disabled={index === 2} onPress={() => pager.current?.next()} style={{ padding: 12 }}><Text>→</Text></Pressable></View><Pressable accessibilityRole="button" onPress={() => setReduce(v => !v)} style={{ padding: 12, backgroundColor: '#e6edde', borderRadius: 20 }}><Text>Motion: {reduce ? 'reduced' : 'system'}</Text></Pressable></View>;
}
